class Solution {
    public int mostFrequent(int[] nums, int key) {
        int[] count = new int[1001];
        int maxCount = 0, result = 0;
        for (int i = 0; i < nums.length - 1; i++) {
            if (nums[i] == key) {
                count[nums[i + 1]]++;
                if (count[nums[i + 1]] > maxCount) {
                    maxCount = count[nums[i + 1]];
                    result = nums[i + 1];
                }
            }
        }
        return result;
    }
}
